 MediaFiles(Context c){context=c.getApplicationContext();resolver=c.getContentResolver();prefs=c.getSharedPreferences("files",0);synchronized(MediaFiles.class){if(database==null)database=new SQLiteOpenHelper(context,"gallery.db",null,2){public void onCreate(SQLiteDatabase d){d.execSQL("CREATE TABLE media(id TEXT PRIMARY KEY,uri TEXT UNIQUE,name TEXT,mime TEXT,bytes INTEGER,created INTEGER,pending INTEGER,published INTEGER NOT NULL DEFAULT 0)");}public void onUpgrade(SQLiteDatabase d,int a,int b){if(a<2){d.execSQL("ALTER TABLE media ADD COLUMN published INTEGER NOT NULL DEFAULT 0");d.execSQL("UPDATE media SET published=rowid WHERE pending=0");}}}.getWritableDatabase();db=database;}migrate();}
