 void setting(JSONObject j)throws IOException{String key=j.optString("key"),value=j.optString("value");switch(key){case "folder"->{value=value.replace('\\','/').replaceAll("/+$","");if(!value.startsWith("DCIM/")||value.contains("..")||value.length()>160||!value.matches("[\\p{L}\\p{N}_ /.-]+"))throw new IOException(com.daniil.wristlens.shared.Strings.tr(com.daniil.wristlens.shared.R.string.wl_123));}case "pattern"->{if(!List.of("standard","millis","iso","wristlens").contains(value))throw new IOException(com.daniil.wristlens.shared.Strings.tr(com.daniil.wristlens.shared.R.string.wl_124));}case "photoType"->{if(!List.of("jpeg","png","webp").contains(value))throw new IOException(com.daniil.wristlens.shared.Strings.tr(com.daniil.wristlens.shared.R.string.wl_125));}case "videoType"->{if(!List.of("avc","hevc","webm").contains(value))throw new IOException(com.daniil.wristlens.shared.Strings.tr(com.daniil.wristlens.shared.R.string.wl_126));}default->throw new IOException(com.daniil.wristlens.shared.Strings.tr(com.daniil.wristlens.shared.R.string.wl_127));}prefs.edit().putString(key,value).apply();}
