 private Uri create(boolean video)throws IOException{
  String t=video?videoType():photoType(),ext=video?(t.equals("webm")?"webm":"mp4"):t.equals("jpeg")?"jpg":t,mime=video?(t.equals("webm")?"video/webm":"video/mp4"):"image/"+t;
  LocalDateTime time=LocalDateTime.now();String name;int collision=0;do{name=FileNames.name(video,pattern(),time,ext,collision++);}while(existsName(name));
  Uri uri;String folder=folder();if(folder.startsWith("content:")){Uri tree=Uri.parse(folder);Uri parent=DocumentsContract.buildDocumentUriUsingTree(tree,DocumentsContract.getTreeDocumentId(tree));uri=DocumentsContract.createDocument(resolver,parent,mime,name);}else{ContentValues v=new ContentValues();v.put(MediaStore.MediaColumns.DISPLAY_NAME,name);v.put(MediaStore.MediaColumns.MIME_TYPE,mime);v.put(MediaStore.MediaColumns.RELATIVE_PATH,folder);v.put(MediaStore.MediaColumns.IS_PENDING,1);uri=resolver.insert(video?MediaStore.Video.Media.EXTERNAL_CONTENT_URI:MediaStore.Images.Media.EXTERNAL_CONTENT_URI,v);}
  if(uri==null)throw new IOException(com.daniil.wristlens.shared.Strings.tr(com.daniil.wristlens.shared.R.string.wl_128));ContentValues v=new ContentValues();v.put("id",UUID.randomUUID().toString());v.put("uri",uri.toString());v.put("name",name);v.put("mime",mime);v.put("bytes",0);v.put("created",System.currentTimeMillis());v.put("pending",1);try{db.insertOrThrow("media",null,v);}catch(Exception e){resolver.delete(uri,null,null);throw new IOException(e);}return uri;
 }
 private boolean existsName(String name){try(Cursor c=db.rawQuery("SELECT 1 FROM media WHERE name=? LIMIT 1",new String[]{name})){if(c.moveToFirst())return true;}try(Cursor c=resolver.query(MediaStore.Files.getContentUri("external"),new String[]{"_id"},"_display_name=? AND relative_path=?",new String[]{name,folder()+"/"},null)){return c!=null&&c.moveToFirst();}catch(Exception e){return false;}}
 Uri save(byte[] jpeg,boolean snapshot)throws IOException{Uri uri=create(false);try(OutputStream out=resolver.openOutputStream(uri)){if(out==null)throw new IOException(com.daniil.wristlens.shared.Strings.tr(com.daniil.wristlens.shared.R.string.wl_119));PhotoWatermark.write(jpeg,photoType(),new CaptureOptions(context).watermark(),System.currentTimeMillis(),out);out.flush();}catch(Exception e){delete(uri);throw new IOException(e);}try{publish(uri);return uri;}catch(Exception e){delete(uri);throw new IOException(e);}}
 Video video()throws IOException{Uri u=create(true);try{ParcelFileDescriptor fd=resolver.openFileDescriptor(u,"rw");if(fd==null)throw new IOException(com.daniil.wristlens.shared.Strings.tr(com.daniil.wristlens.shared.R.string.wl_119));return new Video(u,fd);}catch(Exception e){delete(u);throw new IOException(e);}}
 void publish(Uri u){if(!DocumentsContract.isDocumentUri(context,u)){ContentValues v=new ContentValues();v.put(MediaStore.MediaColumns.IS_PENDING,0);resolver.update(u,v,null,null);}ContentValues v=new ContentValues();v.put("pending",0);try(Cursor c=resolver.query(u,new String[]{OpenableColumns.DISPLAY_NAME,OpenableColumns.SIZE},null,null,null)){if(c!=null&&c.moveToFirst()){v.put("name",c.getString(0));v.put("bytes",c.getLong(1));}}db.beginTransaction();try{long next=latest()+1;if(!prefs.edit().putLong("sequence",next).commit())throw new IllegalStateException(com.daniil.wristlens.shared.Strings.tr(com.daniil.wristlens.shared.R.string.wl_extra_18));v.put("published",next);db.update("media",v,"uri=?",new String[]{u.toString()});db.setTransactionSuccessful();}finally{db.endTransaction();}
  try{com.google.android.gms.wearable.PutDataMapRequest change=com.google.android.gms.wearable.PutDataMapRequest.create(Wire.MEDIA_CHANGED);change.getDataMap().putString("revision",UUID.randomUUID().toString());com.google.android.gms.wearable.Wearable.getDataClient(context).putDataItem(change.asPutDataRequest().setUrgent());}catch(RuntimeException e){android.util.Log.w("WristLens","Media signal",e);}}
 private boolean removeUri(Uri uri)throws IOException{return DocumentsContract.isDocumentUri(context,uri)?DocumentsContract.deleteDocument(resolver,uri):resolver.delete(uri,null,null)>0;}
 void delete(Uri u){try{if(removeUri(u))db.delete("media","uri=?",new String[]{u.toString()});}catch(Exception ignored){}}
 void deleteEntry(String id)throws IOException{Entry e=find(id);if(!removeUri(e.uri))throw new IOException(com.daniil.wristlens.shared.Strings.tr(com.daniil.wristlens.shared.R.string.wl_129));db.delete("media","id=?",new String[]{id});}
 Entry find(String id)throws IOException{try(Cursor c=db.rawQuery("SELECT id,uri,name,mime,bytes,created,published FROM media WHERE id=? AND pending=0",new String[]{id})){if(c.moveToFirst())return entry(c);}throw new IOException(com.daniil.wristlens.shared.Strings.tr(com.daniil.wristlens.shared.R.string.wl_130));}
 private final Map<String,JSONObject> metadata=new LinkedHashMap<>(){protected boolean removeEldestEntry(Map.Entry<String,JSONObject> e){return size()>80;}};
 JSONArray list(int offset){JSONArray a=new JSONArray();try(Cursor c=db.rawQuery("SELECT id,uri,name,mime,bytes,created,published FROM media WHERE pending=0 ORDER BY created DESC LIMIT 20 OFFSET ?",new String[]{Integer.toString(Math.max(0,offset))})){while(c.moveToNext())a.put(details(entry(c)));}return a;}
 private JSONObject details(Entry e){
  JSONObject result=e.json(),cached=metadata.get(e.id());
  if(cached==null){int width=0,height=0;long duration=0;
   try {if(e.mime().startsWith("video/")){try(MediaMetadataRetriever r=new MediaMetadataRetriever()){
     r.setDataSource(context,e.uri());width=Integer.parseInt(r.extractMetadata(MediaMetadataRetriever.METADATA_KEY_VIDEO_WIDTH));height=Integer.parseInt(r.extractMetadata(MediaMetadataRetriever.METADATA_KEY_VIDEO_HEIGHT));duration=Long.parseLong(r.extractMetadata(MediaMetadataRetriever.METADATA_KEY_DURATION));
     String rotation=r.extractMetadata(MediaMetadataRetriever.METADATA_KEY_VIDEO_ROTATION);if("90".equals(rotation)||"270".equals(rotation)){int t=width;width=height;height=t;}
   }}else{BitmapFactory.Options bounds=new BitmapFactory.Options();bounds.inJustDecodeBounds=true;try(InputStream in=resolver.openInputStream(e.uri())){BitmapFactory.decodeStream(in,null,bounds);}width=Math.max(0,bounds.outWidth);height=Math.max(0,bounds.outHeight);}}
   catch(Exception ignored){} // A metadata failure must never hide a saved file.
   cached=Wire.object("width",width,"height",height,"durationMs",duration);metadata.put(e.id(),cached);
  }
  try{result.put("width",cached.optInt("width"));result.put("height",cached.optInt("height"));result.put("durationMs",cached.optLong("durationMs"));}catch(JSONException ignored){}return result;
 }
 int count(){try(Cursor c=db.rawQuery("SELECT COUNT(*) FROM media WHERE pending=0",null)){return c.moveToFirst()?c.getInt(0):0;}}
 JSONObject index(long before,long snapshot){JSONArray items=new JSONArray();long next=0;try(Cursor c=db.rawQuery("SELECT id,uri,name,mime,bytes,created,published,rowid FROM media WHERE pending=0 AND rowid<? AND published<=? ORDER BY rowid DESC LIMIT 100",new String[]{Long.toString(before),Long.toString(snapshot)})){while(c.moveToNext()){items.put(entry(c).json());next=c.getLong(7);}}if(items.length()<100)next=0;return Wire.object("items",items,"next",next,"snapshot",snapshot);}
 long latest(){try(Cursor c=db.rawQuery("SELECT COALESCE(MAX(published),0) FROM media",null)){return Math.max(c.moveToFirst()?c.getLong(0):0,prefs.getLong("sequence",0));}}
 JSONArray since(long sequence){JSONArray a=new JSONArray();try(Cursor c=db.rawQuery("SELECT id,uri,name,mime,bytes,created,published FROM media WHERE pending=0 AND published>? ORDER BY published LIMIT 20",new String[]{Long.toString(sequence)})){while(c.moveToNext())a.put(entry(c).json());}return a;}
