 byte[] thumbnail(String id,int size)throws IOException{Entry e=find(id);Bitmap b;try{b=resolver.loadThumbnail(e.uri,new Size(size,size),null);}catch(Exception fail){if(e.mime.startsWith("video/")){try(MediaMetadataRetriever r=new MediaMetadataRetriever()){r.setDataSource(context,e.uri);b=r.getScaledFrameAtTime(0,MediaMetadataRetriever.OPTION_CLOSEST_SYNC,size,size);}}else b=ImageDecoder.decodeBitmap(ImageDecoder.createSource(resolver,e.uri),(d,i,s)->{Size n=i.getSize();double f=Math.min(1,size/(double)Math.max(n.getWidth(),n.getHeight()));d.setTargetSize(Math.max(1,(int)(n.getWidth()*f)),Math.max(1,(int)(n.getHeight()*f)));d.setAllocator(ImageDecoder.ALLOCATOR_SOFTWARE);});}if(b==null)throw new IOException(com.daniil.wristlens.shared.Strings.tr(com.daniil.wristlens.shared.R.string.wl_131));ByteArrayOutputStream out=new ByteArrayOutputStream();try{b.compress(Bitmap.CompressFormat.JPEG,65,out);return out.toByteArray();}finally{b.recycle();}}
 private void migrate(){synchronized(MediaFiles.class){if(prefs.getBoolean("migrated",false))return;try(Cursor c=resolver.query(MediaStore.Files.getContentUri("external"),new String[]{"_id","_display_name","mime_type","_size","date_added"},"owner_package_name=? AND _display_name LIKE ?",new String[]{context.getPackageName(),"WL_%"},null)){while(c!=null&&c.moveToNext()){ContentValues v=new ContentValues();v.put("id",UUID.randomUUID().toString());v.put("uri",ContentUris.withAppendedId(MediaStore.Files.getContentUri("external"),c.getLong(0)).toString());v.put("name",c.getString(1));v.put("mime",c.getString(2));v.put("bytes",c.getLong(3));v.put("created",c.getLong(4)*1000);v.put("pending",0);db.insertWithOnConflict("media",null,v,SQLiteDatabase.CONFLICT_IGNORE);}}catch(Exception ignored){}prefs.edit().putBoolean("migrated",true).apply();}}
